17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
32	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
33	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
108	        rejectDuplicateTelephone(telephone);
109	        owner.setTelephone(telephone);
110	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
111	        if (owner.getRegistrationDate() == null) {
112	            owner.setRegistrationDate(java.time.LocalDate.now());
113	        }
114	        this.clinicService.saveOwner(owner);
115	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
116	        headers.setLocation(UriComponentsBuilder.newInstance()
117	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
118	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
119	    }
120	
121	    /**
122	     * Normalizes an owner's telephone on create: strips every non-digit character and requires the
123	     * result to be exactly 10 digits. The normalized 10-digit value is stored and returned.
124	     *
125	     * @param telephone the raw telephone as submitted
126	     * @return the normalized 10-digit telephone
127	     * @throws InvalidTelephoneException (400 Bad Request) if the value is not exactly 10 digits after stripping
128	     */
129	    private String normalizeTelephone(String telephone) {
130	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
131	        if (digits.length() != 10) {
132	            throw new InvalidTelephoneException(telephone);
133	        }
134	        return digits;
135	    }
136	
137	    /**
138	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
139	     * multi-character top-level label. Deliberately lenient about the exact character set while still
140	     * rejecting values that are clearly not addresses (e.g. missing '@').
141	     */
142	    private static final java.util.regex.Pattern EMAIL_PATTERN =
143	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
144	
145	    /**
146	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
147	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
148	     * lower-cased before being stored and returned.
149	     *
150	     * @param email the raw email as submitted, may be {@code null}
151	     * @return the lower-cased email, or {@code null} when none was supplied
152	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
153	     */
154	    private String normalizeEmail(String email) {
155	        if (email == null || email.isBlank()) {
156	            return null;
157	        }
158	        String trimmed = email.trim();
159	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
160	            throw new InvalidEmailException(email);
161	        }
162	        return trimmed.toLowerCase(java.util.Locale.ROOT);
163	    }
164	
165	    /**
166	     * Rejects creating an owner whose normalized telephone is already used by another owner.
167	     * Telephones of existing owners are normalized the same way (all non-digit characters stripped)
168	     * before comparison, so equivalent numbers submitted in different formats are still treated as
169	     * duplicates.
170	     *
171	     * @param telephone the normalized 10-digit telephone of the owner being created
172	     * @throws DuplicateTelephoneException (409 Conflict) if another owner already uses this telephone
173	     */
174	    private void rejectDuplicateTelephone(String telephone) {
175	        boolean duplicate = this.clinicService.findAllOwners().stream()
176	            .map(Owner::getTelephone)
177	            .filter(existing -> existing != null)
178	            .map(existing -> existing.replaceAll("\\D", ""))
179	            .anyMatch(telephone::equals);
180	        if (duplicate) {
181	            throw new DuplicateTelephoneException(telephone);
182	        }
183	    }
184	
185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
188	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
189	        if (currentOwner == null) {
190	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	        }
192	        currentOwner.setAddress(ownerFieldsDto.getAddress());
193	        currentOwner.setCity(ownerFieldsDto.getCity());
194	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
195	        currentOwner.setLastName(ownerFieldsDto.getLastName());
196	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
197	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
198	        this.clinicService.saveOwner(currentOwner);
199	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
200	    }
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Transactional
204	    @Override
205	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
206	        Owner owner = this.clinicService.findOwnerById(ownerId);
207	        if (owner == null) {
208	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	        }
210	        this.clinicService.deleteOwner(owner);
211	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
212	    }
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
217	        Owner owner = this.clinicService.findOwnerById(ownerId);
218	        if (owner == null) {
219	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
220	        }
221	        HttpHeaders headers = new HttpHeaders();
222	        Pet pet = petMapper.toPet(petFieldsDto);
223	        owner.setId(ownerId);
224	        pet.setOwner(owner);
225	        pet.getType().setName(null);
226	        this.clinicService.savePet(pet);
227	        PetDto petDto = petMapper.toPetDto(pet);
228	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
229	            .buildAndExpand(pet.getId()).toUri());
230	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
231	    }
232	
233	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
234	    @Override
235	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
236	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
237	        if (currentOwner != null) {
238	            Pet currentPet = this.clinicService.findPetById(petId);
239	            if (currentPet != null) {
240	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
241	                currentPet.setName(petFieldsDto.getName());
242	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
243	                this.clinicService.savePet(currentPet);
244	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
245	            }
246	        }
247	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
248	    }
249	
250	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
251	    @Override
252	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
253	        HttpHeaders headers = new HttpHeaders();
254	        Visit visit = visitMapper.toVisit(visitFieldsDto);
255	        Pet pet = new Pet();
256	        pet.setId(petId);
257	        visit.setPet(pet);
258	        this.clinicService.saveVisit(visit);
259	        VisitDto visitDto = visitMapper.toVisitDto(visit);
260	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
261	            .buildAndExpand(visit.getId()).toUri());
262	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
263	    }
264	
265	
266	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
267	    @Override
268	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
269	        Owner owner = this.clinicService.findOwnerById(ownerId);
270	        if (owner != null) {
271	            Pet pet = owner.getPet(petId);
272	            if (pet != null) {
273	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
274	            }
275	        }
276	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
277	    }
278	}
